import versions from "./image-versions.json";

/**
 * next/image loader for the static export: points each srcset width at the WebP
 * rendition pre-generated by scripts/optimize-images.mjs, so
 * /images/facility/floor/press-row.jpg at 828w becomes /img-opt/facility/floor/press-row-828.webp?v=<hash>.
 * The ?v= content hash changes when the original is replaced, so caches never serve the old photo.
 * Anything outside /images (SVGs, remote or data URLs) is served as-is.
 */
export default function imageLoader({ src, width }: { src: string; width: number; quality?: number }) {
  const match = /^\/images\/(.+)\.(?:jpe?g|png|webp)$/i.exec(src);
  if (!match) return src;
  const version = (versions as Record<string, string | undefined>)[src];
  return `/img-opt/${match[1]}-${width}.webp${version ? `?v=${version}` : ""}`;
}
